/**
 * Место, куда панель вписывает свой набор прав.
 *
 * Пустой у ядра: значения принадлежат панели, и она дописывает сюда `values`
 * своим объявлением — см. `src/types/permissions.d.ts`. Пустой интерфейс не
 * подходит под `{ values: … }`, поэтому у панели без объявления `PapiPermission`
 * честно схлопывается в `string`.
 *
 * Отдельным `.d.ts`, а не рядом с типом: `declare global` в обычном модуле
 * запрещают правила eslint (`no-namespace`), а файлы объявлений они не
 * проверяют. Тем же файлом панель объявляет и ключи каталога — `formatjs.d.ts`.
 */
declare namespace Papi {
  interface Permissions {}
}
